CREATE TABLE `professional_commissions` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`public_id` CHAR(36) NOT NULL,`tenant_id` BIGINT UNSIGNED NOT NULL,`payment_id` BIGINT UNSIGNED NOT NULL,`professional_id` BIGINT UNSIGNED NOT NULL,`appointment_id` BIGINT UNSIGNED NOT NULL,`commission_type` ENUM('PERCENTAGE', 'FIXED') NOT NULL,`commission_value` INTEGER UNSIGNED NOT NULL,`rule_source` ENUM('OVERRIDE', 'DEFAULT') NOT NULL,`base_amount_cents` BIGINT UNSIGNED NOT NULL,`commission_amount_cents` BIGINT UNSIGNED NOT NULL,`status` ENUM('ACTIVE', 'CANCELED') NOT NULL DEFAULT 'ACTIVE',`canceled_at` DATETIME(3) NULL,`canceled_reason` VARCHAR(500) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `professional_commissions_public_id_key` (`public_id`),UNIQUE INDEX `professional_commissions_payment_id_key` (`payment_id`),INDEX `professional_commissions_tenant_id_professional_id_created_idx` (`tenant_id`,`professional_id`,`created_at`),INDEX `professional_commissions_tenant_id_status_created_at_idx` (`tenant_id`,`status`,`created_at`),CONSTRAINT `professional_commissions_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `professional_commissions_payment_id_fkey` FOREIGN KEY (`payment_id`) REFERENCES `payments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `professional_commissions_professional_id_fkey` FOREIGN KEY (`professional_id`) REFERENCES `professionals`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,CONSTRAINT `professional_commissions_appointment_id_fkey` FOREIGN KEY (`appointment_id`) REFERENCES `appointments`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
